Coding a market tracker

I want to build a simple tool for my website where I can input farmers markets and their locations, so that customers can search for markets near them, specifically in LA. Help me with the code?

Great idea — here’s a drop-in “Farmers Market Locator” you can paste into your web page. You’ll be able to edit the markets list yourself (just update the JSON at the top), and customers can search by ZIP/city or use their location to find nearby markets around LA.

<div id="fm-app" class="fm-wrap">
<h2 class="fm-title">Find a Farmers Market Near You</h2>

<div class="fm-controls">
<input id="fm-query" class="fm-input" placeholder="Type a ZIP, city, or address (press Enter)" />
<button id="fm-near-me" class="fm-btn fm-btn-secondary" type="button">Use My Location</button>
</div>

<div id="fm-meta" class="fm-meta"></div>

<div class="fm-grid">
<div id="fm-map" class="fm-map"></div>
<div id="fm-results" class="fm-results"></div>
</div>
</div>

<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>

<style>
.fm-wrap{max-width:1100px;margin:auto;padding:16px}
.fm-controls{display:flex;gap:10px;flex-wrap:wrap}
.fm-input{flex:1;min-width:260px;padding:10px;border-radius:10px;border:1px solid #ddd}
.fm-btn{padding:10px 14px;border-radius:10px;border:1px solid #111;background:#111;color:#fff;cursor:pointer}
.fm-btn-secondary{background:#fff;color:#111}
.fm-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:14px;margin-top:14px}
.fm-map{height:520px;border-radius:14px;border:1px solid #eee}
.fm-results{max-height:520px;overflow:auto;border:1px solid #eee;border-radius:14px;padding:10px;background:#fff}
.fm-card{border:1px solid #eee;border-radius:14px;padding:12px;margin-bottom:10px;cursor:pointer}
.fm-card:hover{border-color:#bbb}
.fm-card.fm-selected{border-color:#111;box-shadow:0 0 0 2px #111 inset}
.fm-card h3{margin:0 0 6px;font-size:16px}
.fm-pill{display:inline-block;border:1px solid #ddd;border-radius:999px;padding:3px 8px;font-size:12px;margin-right:6px;margin-bottom:6px}
.fm-pill-closed{border-color:#c00;color:#c00}
.fm-meta{margin-top:8px;opacity:.85;font-size:13px}

/* remove tile seams */
.leaflet-container{background:#f5f5f5}
.leaflet-tile{border:none!important;outline:none!important;transform:translateZ(0)}
.leaflet-pane img{image-rendering:auto!important;box-shadow:none!important}

@media(max-width:900px){
.fm-grid{grid-template-columns:1fr}
.fm-map{height:360px}
}
</style>

<script>
/* ================= CONFIG ================= */
const DEFAULT_CENTER = { lat: 34.0522, lng: -118.2437 };
const RADIUS_TYPED = 50;
const RADIUS_NEAR_ME = 100;
const ZOOM_TYPED = 12;
const ZOOM_PIN = 15;
const FIT_MAX = 13;

/* ================= HELPERS ================= */
function miles(a,b,c,d){
const R=3958.8,t=x=>x*Math.PI/180;
const dLat=t(c-a),dLng=t(d-b);
const h=Math.sin(dLat/2)**2+Math.cos(t(a))*Math.cos(t(c))*Math.sin(dLng/2)**2;
return 2*R*Math.asin(Math.sqrt(h));
}

async function geocode(q){
const r=await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=us&q=${encodeURIComponent(q)}`);
const d=await r.json();
return d.length?{lat:+d[0].lat,lng:+d[0].lon}:null;
}

function scrollListTop(){
document.getElementById("fm-results").scrollTop = 0;
}

/* ================= DATA (ALL MARKETS) ================= */
const MARKETS = [ /* ← your full 96-market array lives here exactly as before */ ];

/* ================= MAP ================= */
let map=L.map("fm-map").setView([DEFAULT_CENTER.lat,DEFAULT_CENTER.lng],9);
L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{attribution:"© OpenStreetMap"}).addTo(map);
let layer=L.layerGroup().addTo(map), byId=new Map(), selected=null;

/* ================= RENDER ================= */
function render(list, origin=null, label=""){
layer.clearLayers(); byId.clear(); scrollListTop();

document.getElementById("fm-meta").textContent =
origin ? `Closest markets to ${label} (${list.length})` : `Showing ${list.length} markets`;

const bounds=[];
if(origin) bounds.push([origin.lat,origin.lng]);

list.forEach(m=>{
const mk=L.marker([m.lat,m.lng]).addTo(layer).bindPopup(`
<b>${m.name}</b><br>${m.address}, ${m.city}<br>
${m.days} • ${m.hours}<br>${m.status}
`);
mk.on("click",()=>{
map.setView([m.lat,m.lng],Math.max(map.getZoom(),ZOOM_PIN),{animate:true});
select(m.id);
});
byId.set(m.id,mk);
bounds.push([m.lat,m.lng]);
});

if(bounds.length>1) map.fitBounds(bounds,{padding:[30,30],maxZoom:FIT_MAX});

const box=document.getElementById("fm-results");
box.innerHTML=list.map(m=>`
<div class="fm-card ${selected===m.id?"fm-selected":""}" data-id="${m.id}">
<h3>${m.name}</h3>
<div>
<span class="fm-pill">${m.days}</span>
<span class="fm-pill">${m.hours}</span>
${m._miles?`<span class="fm-pill">${m._miles.toFixed(1)} mi</span>`:""}
${m.status==="CLOSED"?`<span class="fm-pill fm-pill-closed">CLOSED</span>`:""}
</div>
<div>${m.address}, ${m.city}</div>
</div>
`).join("");

box.querySelectorAll(".fm-card").forEach(c=>{
c.onclick=()=>{
const id=+c.dataset.id;
select(id);
const mk=byId.get(id);
if(mk){
map.setView(mk.getLatLng(),Math.max(map.getZoom(),ZOOM_PIN),{animate:true});
mk.openPopup();
}
};
});
}

function select(id){
selected=id;
document.querySelectorAll(".fm-card").forEach(c=>{
c.classList.toggle("fm-selected",+c.dataset.id===id);
});
}

/* ================= SEARCH ================= */
async function update(){
const q=document.getElementById("fm-query").value.trim();
if(!q){ render(MARKETS); return; }

const o=await geocode(q);
if(o){
map.setView([o.lat,o.lng],Math.max(map.getZoom(),ZOOM_TYPED),{animate:true});
const near=MARKETS.map(m=>({...m,_miles:miles(o.lat,o.lng,m.lat,m.lng)}))
.filter(m=>m._miles<=RADIUS_TYPED)
.sort((a,b)=>a._miles-b._miles);
render(near,o,q);
}
}

document.getElementById("fm-query").onkeydown=e=>{
if(e.key==="Enter"){e.preventDefault();update();}
};

document.getElementById("fm-near-me").onclick=()=>{
navigator.geolocation.getCurrentPosition(p=>{
const o={lat:p.coords.latitude,lng:p.coords.longitude};
map.setView([o.lat,o.lng],Math.max(map.getZoom(),ZOOM_TYPED),{animate:true});
const near=MARKETS.map(m=>({...m,_miles:miles(o.lat,o.lng,m.lat,m.lng)}))
.filter(m=>m._miles<=RADIUS_NEAR_ME)
.sort((a,b)=>a._miles-b._miles);
render(near,o,"your location");
});
};

render(MARKETS);
</script>

